const http = require('http');
const express = require('express');
const { WebSocketServer } = require('ws');
const { GridTelemetry } = require('../services/grid');
const { authenticateGridOperator } = require('../auth/operator');

const app = express();
const server = http.createServer(app);
const wss = new WebSocketServer({ noServer: true });

server.on('upgrade', async (req, socket, head) => {
  const operator = await authenticateGridOperator(req);
  if (!operator) {
    socket.write('HTTP/1.1 401 Unauthorized\r\n\r\n');
    socket.destroy();
    return;
  }

  const protoHeader = req.headers['sec-websocket-protocol'] || '';
  const match = protoHeader.match(/substation-([a-zA-Z0-9_-]+)/);

  if (!match) {
    socket.destroy();
    return;
  }

  const substationId = match[1];

  // Verify operator is certified and assigned to the requested grid substation
  if (!operator.authorizedSubstations?.includes(substationId)) {
    socket.write('HTTP/1.1 403 Forbidden\r\n\r\n');
    socket.destroy();
    return;
  }

  wss.handleUpgrade(req, socket, head, (ws) => {
    GridTelemetry.subscribeToSubstation(substationId, ws);
  });
});

server.listen(9000);
